class Solution { public:long long incremovableSubarrayCount(vector<int>& nums){int n=nums.size(),prefixEnd=0;while(prefixEnd+1<n&&nums[prefixEnd]<nums[prefixEnd+1])++prefixEnd;if(prefixEnd==n-1)return 1LL*n*(n+1)/2;long long answer=prefixEnd+2LL;for(int suffixStart=n-1;suffixStart>0&&(suffixStart==n-1||nums[suffixStart]<nums[suffixStart+1]);--suffixStart){while(prefixEnd>=0&&nums[prefixEnd]>=nums[suffixStart])--prefixEnd;answer+=prefixEnd+2LL;}return answer;} };
